/* ===== Typography ===== */
h1, h2, h3, h4, h5, h6 { line-height: 1.2; font-weight: 700; }
h1 { font-family: var(--font-serif); font-size: 3rem; }
h2 { font-family: var(--font-serif); font-size: 2.25rem; }
