  border-left: 3px solid transparent;
}
.wwd-tab:hover { color: rgba(255,255,255,0.85); background: rgba(255,255,255,0.05); }
.wwd-tab.active {
  color: var(--white); background: rgba(255,255,255,0.08);
  border-left-color: var(--gold);
}
.wwd-panel { display: none; }
.wwd-panel.active { display: block; }
.wwd-panel h3 {
  font-family: var(--font-serif); font-size: 1.75rem;
  color: var(--white); margin-bottom: 20px;
}
.wwd-panel p {
  color: rgba(255,255,255,0.75); font-size: 1.05rem;
  line-height: 1.75; margin-bottom: 24px; max-width: 560px;
}
.wwd-panel ul {
  display: flex; flex-wrap: wrap; gap: 8px 24px;
  margin-bottom: 28px;
}
.wwd-panel ul li {
  color: rgba(255,255,255,0.7); font-size: 0.95rem;
  padding-left: 16px; position: relative;
}
.wwd-panel ul li::before {
  content: '\00B7'; position: absolute; left: 0; color: var(--gold); font-weight: 700;
}

/* ===== Newsletter ===== */
.newsletter {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--navy-mid) 0%, var(--navy) 100%);
}
.newsletter-inner {
  display: flex; align-items: center; justify-content: space-between; gap: 40px;
}
.newsletter-text h2 { color: var(--white); font-size: 1.75rem; margin-bottom: 8px; }
.newsletter-text p { color: rgba(255,255,255,0.7); font-size: 1rem; }
.newsletter-form {
  display: flex; gap: 12px; flex-shrink: 0;
}
.newsletter-form input {
  padding: 14px 20px; width: 300px; border: 1px solid rgba(255,255,255,0.2);
  border-radius: 2px; background: rgba(255,255,255,0.08);
  color: var(--white); font-size: 0.9rem;
  transition: border-color var(--transition);
}
.newsletter-form input::placeholder { color: rgba(255,255,255,0.4); }
.newsletter-form input:focus { outline: none; border-color: var(--gold); }

/* ===== Latest Insights ===== */
.latest-insights { padding: 80px 0; background: var(--white); }
.latest-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 28px; margin-top: 48px; }
.latest-card { transition: transform var(--transition); }
.latest-card:hover { transform: translateY(-3px); }
.latest-card-img {
  height: 200px; margin-bottom: 16px; border-radius: 4px; overflow: hidden;
}
.latest-card-img-bg {
  width: 100%; height: 100%;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
}
.latest-card .tag {
  display: inline-block; font-size: 0.7rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.1em;
  color: var(--teal); margin-bottom: 8px;
}
.latest-card h3 {
  font-size: 1.05rem; font-weight: 600; line-height: 1.45;
  margin-bottom: 10px; color: var(--text-primary);
}
.latest-card .date {
  font-size: 0.8rem; color: var(--text-light);
}

/* ===== Our Commitment ===== */
.our-commitment {
  padding: 80px 0; background: var(--gray-50);
}
.commitment-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 48px;
}
.commitment-card {
  padding: 32px 24px; background: var(--white); border-radius: 4px;
  border-top: 3px solid transparent; transition: all var(--transition);
  box-shadow: var(--shadow-sm);
}
.commitment-card:hover { border-top-color: var(--gold); box-shadow: var(--shadow-md); }
.commitment-card h3 {
  font-size: 1.05rem; font-weight: 700; margin-bottom: 12px; color: var(--navy);
}
.commitment-card p {
  font-size: 0.9rem; color: var(--text-secondary); line-height: 1.65; margin-bottom: 18px;
}
.commitment-card .btn-link { font-size: 0.8rem; }

/* ===== Services Page ===== */
.service-categories { padding: 80px 0; }
.services-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px;
}
.service-card {
  padding: 36px 28px; background: var(--white);
  border: 1px solid var(--gray-200); border-radius: 4px;
  transition: all var(--transition); position: relative; overflow: hidden;
}
.service-card::before {
  content: ''; position: absolute; top: 0; left: 0; right: 0;
  height: 3px; background: var(--gold); transform: scaleX(0);
  transition: transform var(--transition); transform-origin: left;
}
.service-card:hover { box-shadow: var(--shadow-md); border-color: transparent; }
.service-card:hover::before { transform: scaleX(1); }
.service-card .card-number {
  font-family: var(--font-serif); font-size: 2.5rem; font-weight: 700;
  color: var(--gray-200); margin-bottom: 16px; line-height: 1;
}
.service-card h3 {
  font-size: 1.15rem; font-weight: 700; margin-bottom: 12px; color: var(--navy);
}
.service-card p {
  font-size: 0.92rem; color: var(--text-secondary); line-height: 1.65; margin-bottom: 20px;
}

/* ===== Capabilities Grid ===== */
.capabilities-section { padding: 60px 0; }
.capabilities-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 40px;
}
.capability-card {
  padding: 28px 24px; background: var(--white);
  border: 1px solid var(--gray-200); border-radius: 4px;
  transition: all var(--transition);
}
.capability-card:hover {
  box-shadow: var(--shadow-md); border-color: var(--teal);
}
.capability-card h3 {
  font-size: 1rem; font-weight: 700; margin-bottom: 10px; color: var(--navy);
}
.capability-card p {
  font-size: 0.88rem; color: var(--text-secondary); line-height: 1.6; margin-bottom: 14px;
}
.capability-card .btn-link { font-size: 0.78rem; }

/* ===== Featured Partners (Carousel) ===== */
.featured-partners { padding: 60px 0; background: var(--gray-50); }
.carousel-wrapper { position: relative; margin-top: 40px; overflow: hidden; }
.carousel-track {
  display: flex; transition: transform 0.5s ease;
}
.carousel-slide {
  min-width: 100%; padding: 0 40px;
}
.carousel-card {
  display: grid; grid-template-columns: 1fr 1fr; gap: 40px;
  background: var(--white); border-radius: 4px; padding: 40px;
  box-shadow: var(--shadow-sm);
}
.carousel-card-img {
  height: 220px; border-radius: 4px; overflow: hidden;
}
.carousel-card-img-bg {
  width: 100%; height: 100%;
  background: linear-gradient(135deg, var(--navy-mid) 0%, var(--teal-dark) 100%);
}
.carousel-card-content h3 {
  font-family: var(--font-serif); font-size: 1.35rem;
  margin-bottom: 12px; color: var(--navy);
}
.carousel-card-content p {
  font-size: 0.92rem; color: var(--text-secondary); line-height: 1.65; margin-bottom: 16px;
}
.carousel-controls {
  display: flex; align-items: center; justify-content: center;
  gap: 16px; margin-top: 24px;
}
.carousel-btn {
  width: 44px; height: 44px; border-radius: 50%;
  border: 1.5px solid var(--gray-300); display: flex;
  align-items: center; justify-content: center;
  font-size: 1.1rem; color: var(--text-secondary);
  transition: all var(--transition);
}
.carousel-btn:hover { border-color: var(--teal); color: var(--teal); }
.carousel-dots { display: flex; gap: 8px; }
.carousel-dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: var(--gray-300); transition: all var(--transition);
}
.carousel-dot.active { background: var(--teal); width: 24px; border-radius: 4px; }

/* ===== Deal Flow CTA ===== */
.deal-flow-cta {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 100%);
  text-align: center;
}
.deal-flow-cta h2 { color: var(--white); margin-bottom: 16px; }
.deal-flow-cta p { color: rgba(255,255,255,0.7); font-size: 1.05rem; margin-bottom: 32px; max-width: 520px; margin-left: auto; margin-right: auto; }

/* ===== Testimonial ===== */
.testimonial { padding: 80px 0; background: var(--white); }
.testimonial-inner {
  max-width: 800px; margin: 0 auto; text-align: center;
}
.testimonial-inner blockquote {
  font-family: var(--font-serif); font-size: 1.5rem;
  line-height: 1.6; color: var(--text-primary); margin-bottom: 24px;
}
.testimonial-inner .author {
  font-size: 0.9rem; color: var(--text-secondary);
}
.testimonial-inner .author strong { color: var(--navy); }
.testimonial-accent {
  width: 60px; height: 3px; background: var(--gold);
  margin: 0 auto 28px;
}

/* ===== Featured Topics Sidebar ===== */
.featured-topics-section { padding: 60px 0; background: var(--gray-50); }
.ft-layout { display: grid; grid-template-columns: 1fr 300px; gap: 40px; }
.ft-sidebar { padding: 28px; background: var(--white); border-radius: 4px; box-shadow: var(--shadow-sm); align-self: start; }
.ft-sidebar h4 {
  font-size: 0.9rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.08em; margin-bottom: 16px; padding-bottom: 12px;
  border-bottom: 2px solid var(--gold); color: var(--navy);
}
.ft-sidebar ul li { margin-bottom: 4px; }
.ft-sidebar ul li a {
  display: block; padding: 10px 12px; border-radius: 4px;
  font-size: 0.9rem; color: var(--text-primary);
  transition: all var(--transition);
}
.ft-sidebar ul li a:hover { background: var(--gray-50); color: var(--teal); }

/* ===== Property Types CTA ===== */
.property-types-cta { padding: 60px 0; }
.pt-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; margin-top: 40px; }
.pt-card {
  padding: 24px 16px; text-align: center;
  background: var(--gray-50); border-radius: 4px;
  transition: all var(--transition); cursor: pointer;
}
.pt-card:hover { background: var(--navy); color: var(--white); }
.pt-card h4 { font-size: 0.9rem; font-weight: 600; }
.pt-card-icon {
  font-size: 1.5rem; margin-bottom: 10px; display: block;
}

/* ===== Related Services ===== */
.related-services { padding: 60px 0; background: var(--gray-50); }
.related-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 32px; }
.related-card {
  display: flex; align-items: center; gap: 16px;
  padding: 20px; background: var(--white); border-radius: 4px;
  transition: all var(--transition); box-shadow: var(--shadow-sm);
}
.related-card:hover { box-shadow: var(--shadow-md); }
.related-card-icon {
  width: 48px; height: 48px; border-radius: 4px;
  background: var(--gray-50); display: flex;
  align-items: center; justify-content: center;
  font-size: 1.2rem; flex-shrink: 0;
}
.related-card h4 { font-size: 0.92rem; font-weight: 600; color: var(--navy); }
.related-card p { font-size: 0.8rem; color: var(--text-secondary); margin-top: 2px; }

/* ===== Related Insights ===== */
.related-insights { padding: 60px 0; }
.related-insights-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 32px; }

/* ===== Plan/Lease What We Do ===== */
.pl-what-we-do { padding: 80px 0; background: var(--gray-50); }
.pl-wwd-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; margin-top: 40px; }
.pl-wwd-card {
  padding: 32px; background: var(--white); border-radius: 4px;
  border-left: 4px solid var(--teal); box-shadow: var(--shadow-sm);
}
.pl-wwd-card h3 {
  font-size: 1.1rem; font-weight: 700; color: var(--navy); margin-bottom: 10px;
}
.pl-wwd-card p {
  font-size: 0.92rem; color: var(--text-secondary); line-height: 1.65;
}

/* ===== Design Build Capabilities ===== */
.db-capabilities { padding: 60px 0; }
.db-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 32px; margin-top: 40px; }
.db-card {
  padding: 40px; background: var(--white); border: 1px solid var(--gray-200);
  border-radius: 4px; transition: all var(--transition);
}
.db-card:hover { box-shadow: var(--shadow-md); border-color: var(--teal); }
.db-card-icon {
  width: 56px; height: 56px; border-radius: 4px;
  background: var(--gray-50); display: flex;
  align-items: center; justify-content: center;
  font-size: 1.5rem; margin-bottom: 20px;
}
.db-card h3 {
  font-size: 1.2rem; font-weight: 700; color: var(--navy); margin-bottom: 12px;
}
.db-card p {
  font-size: 0.92rem; color: var(--text-secondary); line-height: 1.7; margin-bottom: 20px;
}

/* ===== Partnership Highlight ===== */
.partnership-highlight {
  padding: 80px 0;
  background: linear-gradient(135deg, var(--navy) 0%, var(--teal-dark) 100%);
}
.partnership-inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
}
.partnership-text h2 { color: var(--white); margin-bottom: 20px; }
.partnership-text p {
  color: rgba(255,255,255,0.8); font-size: 1.05rem; line-height: 1.75; margin-bottom: 24px;
}
.partnership-stats { display: grid; grid-template-columns: repeat(2, 1fr); gap: 24px; }
.partnership-stat {
  padding: 24px; background: rgba(255,255,255,0.08); border-radius: 4px;
  text-align: center;
}
.partnership-stat .stat-value {
  font-family: var(--font-serif); font-size: 2rem; font-weight: 700;
  color: var(--gold); margin-bottom: 4px;
}
.partnership-stat .stat-label {
  font-size: 0.82rem; color: rgba(255,255,255,0.7);
  text-transform: uppercase; letter-spacing: 0.06em;
}

/* ===== Intro Statement ===== */
.intro-statement { padding: 60px 0; }
.intro-inner {
  max-width: 800px; margin: 0 auto; text-align: center;
}
.intro-inner h2 { margin-bottom: 16px; }
.intro-inner p {
  font-size: 1.1rem; color: var(--text-secondary); line-height: 1.75;
}

/* ===== Footer ===== */
.site-footer {
  background: var(--navy); padding: 60px 0 0;
}
.footer-grid {
  display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 32px;
  padding-bottom: 48px; border-bottom: 1px solid rgba(255,255,255,0.08);
}
.footer-brand .logo { margin-bottom: 16px; display: inline-block; }
.footer-brand p {
  color: rgba(255,255,255,0.5); font-size: 0.88rem; line-height: 1.65; max-width: 280px;
}
.footer-col h4 {
  font-size: 0.78rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.1em; color: var(--gold); margin-bottom: 16px;
}
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a {
  font-size: 0.88rem; color: rgba(255,255,255,0.6);
  transition: color var(--transition);
}
.footer-col ul li a:hover { color: var(--white); }
.footer-bottom {
  display: flex; align-items: center; justify-content: space-between;
  padding: 24px 0; flex-wrap: wrap; gap: 12px;
}
.footer-bottom p {
  font-size: 0.78rem; color: rgba(255,255,255,0.35);
}
.footer-legal { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-legal a {
  font-size: 0.78rem; color: rgba(255,255,255,0.45);
  transition: color var(--transition);
}
.footer-legal a:hover { color: rgba(255,255,255,0.8); }

/* ===== Page Spacer ===== */
.page-spacer { height: var(--header-height); }

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .services-grid { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .about-inner { grid-template-columns: 1fr; gap: 32px; }
  .partnership-inner { grid-template-columns: 1fr; }
  .ft-layout { grid-template-columns: 1fr; }
  .carousel-card { grid-template-columns: 1fr; }
  .carousel-card-img { height: 180px; }
}

@media (max-width: 768px) {
  :root { --header-height: 64px; }
  h1 { font-size: 2rem; }
  h2 { font-size: 1.75rem; }
  .section-padding { padding: 60px 0; }
  .section-padding-lg { padding: 72px 0; }

  .main-nav { display: none; }
  .mobile-toggle { display: flex; }

  .hero { min-height: 420px; }
  .hero h1 { font-size: 2rem; }
  .hero-short { min-height: 300px; }
  .hero-short h1 { font-size: 1.75rem; }

  .insights-grid { grid-template-columns: 1fr; }
  .latest-grid { grid-template-columns: 1fr; }
  .services-grid { grid-template-columns: 1fr; }
  .capabilities-grid { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: 1fr; }
  .pt-grid { grid-template-columns: repeat(3, 1fr); }

  .wwd-container { grid-template-columns: 1fr; gap: 24px; }
  .wwd-tabs { flex-direction: row; overflow-x: auto; gap: 0; }
  .wwd-tab { white-space: nowrap; border-left: none; border-bottom: 3px solid transparent; padding: 12px 16px; }
  .wwd-tab.active { border-bottom-color: var(--gold); border-left-color: transparent; }

  .newsletter-inner { flex-direction: column; text-align: center; }
  .newsletter-form { flex-direction: column; width: 100%; }
  .newsletter-form input { width: 100%; }

  .about-inner { grid-template-columns: 1fr; }

  .db-grid { grid-template-columns: 1fr; }
  .pl-wwd-grid { grid-template-columns: 1fr; }
  .related-grid { grid-template-columns: 1fr; }
  .related-insights-grid { grid-template-columns: 1fr; }
  .partnership-stats { grid-template-columns: repeat(2, 1fr); }
  .carousel-slide { padding: 0 8px; }

  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .capabilities-grid { grid-template-columns: 1fr; }
  .pt-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: 1fr; }
  .partnership-stats { grid-template-columns: 1fr; }
  .hero h1 { font-size: 1.65rem; }
}
